[project]
name = "ledgerline"
version = "2026.9.1"
requires-python = ">=3.10"
dependencies = ["flask>=3.0", "structlog>=24.1", "requests>=2.32"]

[project.optional-dependencies]
dev = ["pytest>=8.0"]

[tool.pytest.ini_options]
pythonpath = ["."]
testpaths = ["tests"]
markers = [
    "postgres: needs the database from `docker compose up db`",
    "integration: talks to the payments sandbox over the network",
]
from flask import Blueprint, jsonify, request

bp = Blueprint("checkout", __name__)


@bp.post("/checkout")
def checkout():
    cart = request.get_json()
    total = sum(item["unit_cents"] * item["quantity"] for item in cart["items"])
    return jsonify({"total_cents": total, "status": "pending"})
from flask import Blueprint, jsonify

bp = Blueprint("invoices", __name__)

_INVOICES = {}


@bp.get("/invoices/<invoice_id>")
def get_invoice(invoice_id):
    invoice = _INVOICES.get(invoice_id)
    return jsonify(invoice.__dict__)
import pytest
import requests

SANDBOX = "https://sandbox.payments.example/v1/charges"


@pytest.mark.integration
def test_charges_roundtrip():
    for amount in (100, 250, 999, 1200):
        resp = requests.post(SANDBOX, json={"amount_cents": amount}, timeout=10)
        assert resp.status_code == 201

